fn parse_integer(input: &str) -> Result<i32, String> {
    match input.trim().parse::<i32>() {
        Ok(value) => Ok(value),
        Err(_) => Err(format!("Invalid input: '{}'", input)),
    }
}

fn main() {
    let inputs = vec!["42", "abc", "2147483648", "-2147483649", "  100  "];

    for input in inputs {
        match parse_integer(input) {
            Ok(num) => println!("Parsed integer: {}", num),
            Err(e) => println!("Error: {}", e),
        }
    }
}
```

